tool_input.new_string:
/*
 * 标签宽用 px 而非 em：中文字符实际宽度约等于 1 个 16px 字高（门户根字号 16px），
 * 而 em 随字体度量往往小于中文字形宽度，导致标签盒比文字窄、值左缘参差。
 * 同一列（含独占整行的字段）统一取该列最长标签的字数 × 16px，保证整列取值左对齐。
 */
const LABEL_CHAR_PX = 16
const columnLabelWidths = enterpriseGridRows.reduce((widths, row) => {
  row.forEach((field, columnIndex) => {
    // 独占整行的字段归到第一列，与左侧双列字段共用同一条取值左缘
    const targetIndex = field.full ? 0 : columnIndex
    widths[targetIndex] = Math.max(widths[targetIndex] || 0, [...field.label].length)
  })
  return widths
}, [])

const enterpriseGridFields = enterpriseGridRows.flatMap((row) =>
  row.map((field, columnIndex) => {
    const targetIndex = field.full ? 0 : columnIndex
    return {
      ...field,
      labelWidth: `${columnLabelWidths[targetIndex] * LABEL_CHAR_PX}px`
    }
  })
)

