const { chromium } = require('playwright')

;(async () => {
  const browser = await chromium.launch()
  const page = await browser.newPage({ viewport: { width: 1920, height: 1073 } })
  await page.goto('http://localhost:8092/#/UnifiedLogin?portal=rental-opening', { waitUntil: 'networkidle' })
  await page.waitForTimeout(1500)
  const row = page.locator('.portal-table tbody tr').first()
  await row.getByRole('button', { name: '基本信息', exact: true }).click()
  await page.locator('.rental-detail-dialog').waitFor({ state: 'visible' })
  await page.waitForTimeout(800)
  const box = await page.locator('.rental-enterprise-body').boundingBox()
  await page.screenshot({ path: 'D:/repository/门户/rental-dialog-shot.png', clip: {
    x: Math.max(0, box.x - 90), y: Math.max(0, box.y - 60),
    width: box.width + 140, height: box.height + 90
  }})
  console.log('SHOT OK')
  await browser.close()
})().catch(e => { console.error('ERR', e.message); process.exit(1) })
